 // Hop distance from `src` to every node; -1 where unreachable.
-fn bfs(g: &[[i64]], src: i64) -> [i64] {
-    []
+fn bfs(g: &[[i64]], src: i64) -> [i64] {    let n = len(g)
+    let mut dist: [i64] = []
+    let mut i = 0
+    while i < n {
+        dist = arr_push(dist, -1)
+        i = i + 1
+    }
+    if src < 0 || src >= n {
+        return dist
+    }
+    let mut queue: [i64] = []
+    queue = arr_push(queue, src)
+    dist[src] = 0
+    let mut head = 0
+    while head < len(queue) {
+        let u = queue[head]
+        head = head + 1
+        let nbrs = g[u]
+        let mut k = 0
+        while k < len(nbrs) {
+            let v = nbrs[k]
+            if dist[v] == -1 {
+                dist[v] = dist[u] + 1
+                queue = arr_push(queue, v)
+            }
+            k = k + 1
+        }
+    }
+    dist
 }

